        // Instantiate AdminRest with a SimpleMeterRegistry to avoid micrometer errors
        AdminRest adminRest = new AdminRest(null, new SimpleMeterRegistry());
        // Call the version() method
        Response response = adminRest.version();
        assertNotNull(response);
        Object entity = response.getEntity();
        assertNotNull(entity);
        // Use reflection to invoke the write(OutputStream) method of the anonymous RestStreamingOutput
        Method writeMethod = entity.getClass().getMethod("write", OutputStream.class);
        // Capture output
        ByteArrayOutputStream baos = new ByteArrayOutputStream();
        writeMethod.invoke(entity, baos);
        String output = baos.toString("UTF-8");
        // Build expected JSON from the VersionInfo returned by ConfigUtil.readVersion()
        VersionInfo verInfo = ConfigUtil.readVersion();
        ObjectMapper mapper = new ObjectMapper();
        String expectedJson = mapper.writerWithDefaultPrettyPrinter().writeValueAsString(verInfo);
        // The output should contain the pretty-printed JSON representation of VersionInfo
        assertTrue(output.contains(expectedJson), "Output should contain the VersionInfo JSON");
    }

    @Test
    public void testVersionHandlesExceptionWhenOutputStreamThrows() throws Exception {
        // Instantiate AdminRest with a SimpleMeterRegistry to avoid micrometer errors
        AdminRest adminRest = new AdminRest(null, new SimpleMeterRegistry());
        // Call the version() method
        Response response = adminRest.version();
        assertNotNull(response);
        Object entity = response.getEntity();
        assertNotNull(entity);
        // Use reflection to invoke the write(OutputStream) method
        Method writeMethod = entity.getClass().getMethod("write", OutputStream.class);
        // Create an OutputStream that throws on write and flush to trigger the exception handling path
        OutputStream throwingStream = new OutputStream() {

            @Override
            public void write(int b) throws IOException {
                throw new IOException("simulated write failure");
            }

            @Override
            public void flush() throws IOException {
                throw new IOException("simulated flush failure");
            }
        };
        // The write method catches Throwable internally; invoking it should not throw an exception
        writeMethod.invoke(entity, throwingStream);
    }
